import { t } from '@lingui/core/macro';
import type { AxiosInstance } from 'axios';
import { showApiErrorMessage } from './notifications';

/*
 * Download a file generated by an API endpoint, using the server's filename.
 * The request is made through the API instance, so it is authenticated.
 */
export function downloadApiFile({
  api,
  url,
  params,
  fallbackName
}: {
  api: AxiosInstance;
  url: string;
  params?: Record<string, any>;
  fallbackName: string;
}): Promise<void> {
  return api
    .get(url, { params: params, responseType: 'blob' })
    .then((response) => {
      const name =
        response.headers['content-disposition']?.match(
          /filename="?([^"]+)"?/
        )?.[1] ?? fallbackName;
      const href = URL.createObjectURL(response.data);
      const link = document.createElement('a');
      link.href = href;
      link.download = name;
      link.click();
      URL.revokeObjectURL(href);
    })
    .catch((error) => {
      showApiErrorMessage({
        error: error,
        title: t`Error`,
        message: t`Could not download the file`
      });
    });
}
